{"cmd": "$enc = New-Object System.Text.UTF8Encoding($false)
$dir = 'src\main\java\com\example\starter\aging'
New-Item -ItemType Directory -Force $dir | Out-Null
[System.IO.File]::WriteAllText("$dir\AgingBatch.java", @'
package com.example.starter.aging;

import java.time.Instant;

/**
 * 熟成批次。storedAt 为入库 UTC 时刻；status 取值 AGING（熟成中）/ RELEASED（已放行）。
 */
public record AgingBatch(
        long id,
        String batchCode,
        String requestId,
        Instant storedAt,
        int targetDays,
        String status,
        Instant createdAt) {

    public static final String STATUS_AGING = "AGING";
    public static final String STATUS_RELEASED = "RELEASED";
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\TurnRecord.java", @'
package com.example.starter.aging;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 每日翻面确认。turnDate 为 UTC 自然日，每批次每日最多一条。
 */
public record TurnRecord(
        long id,
        long batchId,
        LocalDate turnDate,
        Instant turnedAt,
        String operatorName,
        String requestId) {
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\TemperatureRecord.java", @'
package com.example.starter.aging;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

/**
 * 温度记录。status 取值 VALID（有效）/ VOID（已作废）；作废仅追加，原记录保留，
 * voidReason/voidedAt/voidRequestId 在未作废时为 null。
 */
public record TemperatureRecord(
        long id,
        long batchId,
        LocalDate recordedDate,
        BigDecimal celsius,
        Instant recordedAt,
        String status,
        String voidReason,
        Instant voidedAt,
        String voidRequestId,
        String requestId) {

    public static final String STATUS_VALID = "VALID";
    public static final String STATUS_VOID = "VOID";
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\ReleaseRecord.java", @'
package com.example.starter.aging;

import java.time.Instant;

/**
 * 质检放行记录。snapshotJson 固化放行时七天的翻面与温度记录编号，之后补录或作废不影响。
 */
public record ReleaseRecord(
        long id,
        long batchId,
        String requestId,
        Instant releasedAt,
        String snapshotJson) {
}
'@, $enc)
[System.IO.File]::WriteAllText('src\main\java\com\example\starter\config\TimeConfig.java', @'
package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 统一 UTC 时钟，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}
'@, $enc)
Get-ChildItem $dir, 'src\main\java\com\example\starter\config'"}

