            ps.setTimestamp(3, Timestamp.from(storedAt));
            ps.setInt(4, targetDays);
            ps.setString(5, AgingBatch.STATUS_AGING);
            ps.setTimestamp(6, Timestamp.from(now));
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

