                .stream().findFirst();
    }

    public Optional<TurnRecord> findTurn(long batchId, LocalDate date) {
        return jdbc.query("SELECT * FROM turn_record WHERE batch_id = ? AND turn_date = ?",
                TURN_MAPPER, batchId, Date.valueOf(date)).stream().findFirst();
